var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Gameplay/Main_Gameplay.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var spawnerObject = UnityEngine.GameObject.Find("EnemySpawner_Manager"); if (spawnerObject == null) throw new System.Exception("EnemySpawner_Manager missing");
var spawner = spawnerObject.GetComponent<SoulHunter.Gameplay.AI.EnemySpawner>(); var so = new UnityEditor.SerializedObject(spawner);
var enemyList = so.FindProperty("_stageEnemyPrefabs"); var eliteList = so.FindProperty("_stageElitePrefabs"); var bossList = so.FindProperty("_stageBossPrefabs"); enemyList.arraySize = 10; eliteList.arraySize = 10; bossList.arraySize = 10;
for (int i = 0; i < 10; i++) { string n = (i + 1).ToString("00"); enemyList.GetArrayElementAtIndex(i).objectReferenceValue = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>($"Assets/Prefabs/Enemies/Gameplay/SH10_L{n}_EnemyGameplay.prefab"); eliteList.GetArrayElementAtIndex(i).objectReferenceValue = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>($"Assets/Prefabs/Enemies/SH10_L{n}_Elite.prefab"); bossList.GetArrayElementAtIndex(i).objectReferenceValue = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>($"Assets/Prefabs/Bosses/Gameplay/SH10_L{n}_BossGameplay.prefab"); }
so.ApplyModifiedPropertiesWithoutUndo(); UnityEditor.EditorUtility.SetDirty(spawnerObject); UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene); UnityEditor.AssetDatabase.SaveAssets(); return new { enemies = enemyList.arraySize, elites = eliteList.arraySize, bosses = bossList.arraySize };
